"use client";

import { useRef, useState, useEffect } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { Heart } from 'lucide-react';

gsap.registerPlugin(ScrollTrigger);

export default function LoveLetterScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const letterRef = useRef<HTMLDivElement>(null);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    // Parallax scrolling for the container
    gsap.fromTo(containerRef.current,
      { opacity: 0, y: 50 },
      {
        opacity: 1,
        y: 0,
        ease: "power2.out",
        duration: 1,
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top 80%",
        }
      }
    );
  }, []);

  useEffect(() => {
    if (isOpen && letterRef.current) {
      // Animate letter sliding out of the envelope
      gsap.to(letterRef.current, {
        y: -300,
        scale: 1.1,
        opacity: 1,
        duration: 1.5,
        ease: "power3.out",
        zIndex: 50
      });
    }
  }, [isOpen]);

  return (
    <section ref={containerRef} className="py-32 px-6 md:px-12 bg-midnight text-warm-ivory relative flex flex-col justify-center items-center min-h-screen overflow-hidden">
      
      {/* Decorative background elements */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div className="absolute -top-[20%] -right-[10%] w-[50%] h-[50%] bg-pink-500/10 rounded-full blur-[120px]" />
        <div className="absolute -bottom-[20%] -left-[10%] w-[50%] h-[50%] bg-red-500/10 rounded-full blur-[120px]" />
      </div>

      <div className="text-center mb-16 relative z-20 transition-opacity duration-1000" style={{ opacity: isOpen ? 0 : 1, pointerEvents: isOpen ? 'none' : 'auto' }}>
        <h2 className="text-3xl md:text-5xl font-serif text-pink-300 drop-shadow-md mb-4">A Special Message for You...</h2>
        <p className="text-warm-ivory/70 text-lg animate-pulse">Tap the heart to open</p>
      </div>

      {/* Envelope Container */}
      <div className="relative w-full max-w-2xl h-[300px] md:h-[400px] flex justify-center items-end mt-10 md:mt-20">
        
        {/* The Letter (Hidden inside initially, slides up) */}
        <div 
          ref={letterRef} 
          className="absolute bottom-0 w-11/12 md:w-4/5 bg-warm-ivory text-midnight p-8 md:p-12 rounded-t-xl shadow-2xl z-10 transform translate-y-10 opacity-0"
        >
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cream-paper.png')] opacity-50 rounded-t-xl mix-blend-overlay"></div>
          <div className="relative z-10">
            <h2 className="text-3xl md:text-5xl font-serif text-deep-burgundy mb-6 italic">
              My Dearest Diya,
            </h2>
            
            <div className="space-y-4 md:space-y-6 text-base md:text-xl font-light leading-relaxed text-midnight/90 font-serif">
              <p>
                When I started building this, I realized that no amount of code, animations, or words could truly capture what you mean to me.
              </p>
              <p>
                You are the quiet peace at the end of a long day and the sudden burst of laughter that catches me off guard. You are my favorite thought.
              </p>
              <p>
                As you celebrate another year of life, I want to celebrate another year of having you in mine. I promise to keep choosing you, every single day, making you smile and making you blush just like this.
              </p>
            </div>

            <div className="mt-10 text-right">
              <p className="text-lg italic font-serif text-midnight/80">Yours always,</p>
              <p className="text-3xl md:text-4xl font-serif text-deep-burgundy mt-2 font-bold">Kuchu Puchu ❤️</p>
            </div>
          </div>
        </div>

        {/* Envelope Back */}
        <div className="absolute bottom-0 w-full h-[250px] md:h-[350px] bg-pink-200 rounded-b-xl shadow-2xl z-0 border-x border-b border-pink-300"></div>

        {/* Envelope Front Flaps (Left and Right) */}
        <div className="absolute bottom-0 w-full h-[250px] md:h-[350px] z-20 pointer-events-none overflow-hidden rounded-b-xl">
           {/* Left Flap */}
           <div className="absolute left-0 bottom-0 w-0 h-0 border-b-[250px] md:border-b-[350px] border-b-pink-300 border-r-[50vw] md:border-r-[336px] border-r-transparent drop-shadow-xl"></div>
           {/* Right Flap */}
           <div className="absolute right-0 bottom-0 w-0 h-0 border-b-[250px] md:border-b-[350px] border-b-pink-200 border-l-[50vw] md:border-l-[336px] border-l-transparent drop-shadow-xl"></div>
        </div>

        {/* Envelope Top Flap */}
        <div 
          className="absolute w-full z-30 origin-top transition-transform duration-1000 ease-in-out"
          style={{ 
            bottom: '250px',
            transform: isOpen ? 'rotateX(180deg)' : 'rotateX(0deg)',
          }}
        >
           {/* Mobile Top Flap */}
           <div className="md:hidden absolute top-0 left-0 w-0 h-0 border-t-[150px] border-t-pink-400 border-l-[50vw] border-r-[50vw] border-l-transparent border-r-transparent drop-shadow-2xl"></div>
           {/* Desktop Top Flap */}
           <div className="hidden md:block absolute top-0 left-0 w-0 h-0 border-t-[200px] border-t-pink-400 border-l-[336px] border-r-[336px] border-l-transparent border-r-transparent drop-shadow-2xl"></div>
        </div>

        {/* The Heart Seal */}
        <button 
          onClick={() => setIsOpen(true)}
          className={`absolute z-40 transform -translate-x-1/2 transition-all duration-700 hover:scale-125 ${isOpen ? 'opacity-0 pointer-events-none scale-150' : 'opacity-100 animate-bounce'}`}
          style={{ 
            left: '50%',
            bottom: '220px', 
          }}
        >
          <div className="relative w-16 h-16 md:w-20 md:h-20 bg-red-500 rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(239,68,68,0.6)] cursor-pointer">
            <Heart className="text-white fill-white w-8 h-8 md:w-10 md:h-10 animate-pulse" />
          </div>
        </button>
        
        {/* Confetti Explosion on Open */}
        {isOpen && (
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50 pointer-events-none">
            {[...Array(20)].map((_, i) => (
              <div 
                key={i}
                className="absolute w-3 h-3 rounded-full bg-pink-500 animate-particle"
                style={{
                  '--tx': `${(Math.random() - 0.5) * 400}px`,
                  '--ty': `${(Math.random() - 0.5) * 400}px`,
                  animationDelay: `${Math.random() * 0.2}s`,
                  backgroundColor: ['#ec4899', '#f43f5e', '#fbbf24', '#ffffff'][Math.floor(Math.random() * 4)]
                } as any}
              />
            ))}
          </div>
        )}
      </div>

      <style dangerouslySetInnerHTML={{__html: `
        @media (min-width: 768px) {
           .envelope-top-flap {
              bottom: 350px !important;
           }
           .envelope-heart {
              bottom: 310px !important;
           }
        }
        @keyframes particleExplosion {
          0% { transform: translate(0, 0) scale(1); opacity: 1; }
          100% { transform: translate(var(--tx), var(--ty)) scale(0); opacity: 0; }
        }
        .animate-particle {
          animation: particleExplosion 1s ease-out forwards;
        }
      `}} />
    </section>
  );
}
