"use client";

import { useState, useRef, useEffect } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { Sparkles, Heart } from 'lucide-react';
import confetti from 'canvas-confetti';

gsap.registerPlugin(ScrollTrigger);

export default function BirthdayScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isCandleBlown, setIsCandleBlown] = useState(false);
  const [showFinalMessage, setShowFinalMessage] = useState(false);
  
  const flameRef = useRef<HTMLDivElement>(null);
  const finalMessageRef = useRef<HTMLDivElement>(null);

  // Scroll animation for the section entering
  useEffect(() => {
    gsap.fromTo(containerRef.current,
      { opacity: 0 },
      {
        opacity: 1,
        duration: 1.5,
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top 50%",
        }
      }
    );
  }, []);

  const handleBlowCandle = () => {
    if (isCandleBlown) return;
    setIsCandleBlown(true);
    
    // Animate flame going out
    if (flameRef.current) {
      gsap.to(flameRef.current, {
        opacity: 0,
        scale: 0,
        duration: 0.5,
        ease: "power2.in",
        onComplete: () => {
          // Trigger confetti
          const duration = 3 * 1000;
          const end = Date.now() + duration;

          const frame = () => {
            confetti({
              particleCount: 5,
              angle: 60,
              spread: 55,
              origin: { x: 0 },
              colors: ['#ff0a54', '#ff477e', '#ff7096', '#ff85a1', '#fbb1bd']
            });
            confetti({
              particleCount: 5,
              angle: 120,
              spread: 55,
              origin: { x: 1 },
              colors: ['#ff0a54', '#ff477e', '#ff7096', '#ff85a1', '#fbb1bd']
            });

            if (Date.now() < end) {
              requestAnimationFrame(frame);
            }
          };
          frame();

          // Trigger final message sequence
          setShowFinalMessage(true);
        }
      });
    }
  };

  useEffect(() => {
    if (showFinalMessage && finalMessageRef.current) {
      gsap.fromTo(finalMessageRef.current,
        { opacity: 0, y: 30 },
        { opacity: 1, y: 0, duration: 1.5, ease: "power2.out", delay: 0.5 }
      );
    }
  }, [showFinalMessage]);

  return (
    <section ref={containerRef} className="py-32 px-6 min-h-screen bg-deep-burgundy text-warm-ivory relative flex flex-col items-center justify-center">
      
      {/* Stars/Sparkles Background - Simplified */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-20">
        {[...Array(20)].map((_, i) => (
          <div 
            key={i}
            className="absolute bg-muted-gold rounded-full"
            style={{
              width: Math.random() * 4 + 1 + 'px',
              height: Math.random() * 4 + 1 + 'px',
              top: Math.random() * 100 + '%',
              left: Math.random() * 100 + '%',
              opacity: Math.random(),
              animation: `twinkle ${Math.random() * 3 + 2}s infinite alternate`
            }}
          />
        ))}
      </div>
      
      <div className="z-10 text-center flex flex-col items-center">
        {!isCandleBlown ? (
          <>
            <h2 className="text-4xl md:text-5xl font-serif text-muted-gold mb-16">
              Make a Wish...
            </h2>
            
            {/* Minimalist interactive candle */}
            <div className="relative cursor-pointer group" onClick={handleBlowCandle}>
              <div className="w-16 h-48 bg-warm-ivory rounded-t-xl mx-auto shadow-[inset_-5px_0_10px_rgba(0,0,0,0.1)] relative">
                {/* Stripes */}
                <div className="absolute top-8 left-0 right-0 h-4 bg-muted-gold/40 transform -skew-y-6" />
                <div className="absolute top-24 left-0 right-0 h-4 bg-muted-gold/40 transform -skew-y-6" />
                
                {/* Wick */}
                <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-1 h-3 bg-[#4a4a4a]" />
                
                {/* Flame */}
                <div ref={flameRef} className="absolute -top-20 left-1/2 -translate-x-1/2 w-10 h-16 origin-bottom">
                  <div className="w-full h-full bg-gradient-to-t from-orange-400 via-yellow-300 to-transparent rounded-[50%_50%_50%_50%_/_60%_60%_40%_40%] animate-flicker filter drop-shadow-[0_0_20px_rgba(253,224,71,0.8)]" />
                  <div className="absolute bottom-2 left-1/2 -translate-x-1/2 w-4 h-6 bg-blue-300/80 rounded-full blur-[2px]" />
                </div>
              </div>
              <p className="mt-12 text-sm uppercase tracking-[0.2em] opacity-50 group-hover:opacity-100 transition-opacity">
                ( Tap the candle to blow it out )
              </p>
            </div>
          </>
        ) : (
          <div ref={finalMessageRef} className="flex flex-col items-center opacity-0 max-w-4xl">
            <h2 className="text-5xl md:text-7xl font-serif text-muted-gold mb-8">
              Happy Birthday, Diya! 🎉
            </h2>
            <p className="text-xl md:text-2xl font-light text-warm-ivory/80 mb-12">
              Here's to you, to us, and to a lifetime of beautiful memories together. I love you more than words can say.
            </p>
            
            {/* Final Media / Gift */}
            <div className="relative w-full max-w-xl mx-auto rounded-2xl overflow-hidden shadow-[0_20px_50px_rgba(200,50,100,0.4)] group cursor-pointer border border-warm-ivory/20 transform hover:scale-[1.02] transition-all duration-700 z-20">
               <img 
                 src="/images/propose pose.JPG" 
                 alt="Our Special Moment" 
                 className="w-full h-auto object-cover transition-transform duration-1000 group-hover:scale-110"
               />
               <div className="absolute inset-0 bg-gradient-to-t from-deep-burgundy/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 flex flex-col justify-end items-center p-8">
                  <Heart className="w-12 h-12 text-pink-500 fill-pink-500 mb-4 animate-bounce" />
                  <h3 className="text-2xl font-serif text-warm-ivory shadow-black drop-shadow-md">My Forever Love</h3>
               </div>
            </div>

            {/* Extra memories collage */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8 w-full max-w-5xl">
              {[
                { src: "/images/amar bou.jpeg", label: "My Beautiful Wife", delay: "delay-100", rotation: "-rotate-3" },
                { src: "/images/beauty.jpeg", label: "Gorgeous", delay: "delay-300", rotation: "rotate-2" },
                { src: "/images/swag pic.jpeg", label: "My Swag Love", delay: "delay-500", rotation: "-rotate-2" },
                { src: "/images/my wife.jpeg", label: "Forever Mine", delay: "delay-700", rotation: "rotate-3" }
              ].map((img, idx) => (
                <div key={idx} className={`relative bg-warm-ivory p-3 pb-8 rounded-lg shadow-xl border border-warm-ivory/30 transform transition-all duration-500 hover:scale-110 hover:z-30 cursor-pointer ${img.rotation} animate-fade-in-up ${img.delay}`}>
                  <div className="relative w-full aspect-square overflow-hidden rounded">
                    <img src={img.src} alt={img.label} className="w-full h-full object-cover" />
                  </div>
                  <p className="absolute bottom-2 left-0 right-0 text-center font-serif text-deep-burgundy text-sm font-semibold">{img.label}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
      
      {/* Add a global style for twinkle and flicker specifically for this component if needed, or tailwind arbitrary values */}
      <style dangerouslySetInnerHTML={{__html: `
        @keyframes flicker {
          0%, 100% { transform: rotate(-2deg) scaleY(1.05); }
          25% { transform: rotate(1deg) scaleY(0.95); }
          50% { transform: rotate(-1deg) scaleY(1); }
          75% { transform: rotate(2deg) scaleY(0.98); }
        }
        @keyframes twinkle {
          0% { opacity: 0.1; }
          100% { opacity: 0.8; transform: scale(1.2); }
        }
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(20px) scale(0.9); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        .animate-fade-in-up {
          animation: fadeInUp 0.8s ease-out forwards;
        }
        .delay-100 { animation-delay: 100ms; }
        .delay-300 { animation-delay: 300ms; }
        .delay-500 { animation-delay: 500ms; }
        .delay-700 { animation-delay: 700ms; }
      `}} />
    </section>
  );
}
